// Parallel driver: reuses p.mjs semantics but async, concurrency N.
import { execFile } from 'node:child_process';
import { EXE, MK } from '/tmp/probe/p.mjs';
const ORDER = ['a','b','c','d','e','f'];
function runAsync(args){
  const argv=[]; for(const k of ORDER) argv.push('--'+k, args[k]===undefined?MK[k]:args[k]);
  return new Promise(res=>execFile(EXE,argv,{encoding:'utf8',maxBuffer:1<<28},(err,so,se)=>{
    if(err) res('ERR('+err.code+')\n'+(so||'')+(se||'')); else res(so);
  }));
}
function extract(slot,out){
  const lines=out.split('\n');
  if(slot==='5'){
    let i=lines.length-1; while(i>=0&&lines[i]==='')i--;
    let j=i; while(j>=0&&!lines[j].includes('</article>'))j--;
    const tail=lines.slice(j+1,i+1);
    const k=tail.lastIndexOf('<p>'+MK.e+'</p>');
    return tail.slice(k+1).join('\n');
  }
  const pos=ORDER.indexOf(slot); let start=0;
  for(let k=0;k<pos;k++) start=lines.indexOf('<p>'+MK[ORDER[k]]+'</p>',start)+1;
  const end=pos<5?lines.indexOf('<p>'+MK[ORDER[pos+1]]+'</p>',start):lines.indexOf('<h1>Combined Document</h1>',start);
  return lines.slice(start,end).join('\n');
}
export async function phaseP(slot,s){
  const args={...MK}; if(slot==='5') args.f=s; else args[slot]=s;
  return extract(slot, await runAsync(args));
}
export async function mapLimit(items,limit,fn){
  const out=new Array(items.length); let i=0;
  await Promise.all(Array.from({length:limit},async()=>{ while(true){const k=i++; if(k>=items.length)return; out[k]=await fn(items[k],k);} }));
  return out;
}
export async function probe(cases, slots=['d','e','5']){
  const jobs=[]; for(const c of cases) for(const s of slots) jobs.push([c,s]);
  const res=await mapLimit(jobs,10,async([c,s])=>[c.name,s,await phaseP(s,c.text)]);
  const byName=new Map();
  for(const [n,s,o] of res){ if(!byName.has(n)) byName.set(n,{}); byName.get(n)[s]=o; }
  return byName;
}
export function report(byName, cases){
  for(const c of cases){
    const r=byName.get(c.name);
    console.log('### '+c.name);
    console.log('IN  '+JSON.stringify(c.text));
    for(const s of Object.keys(r)) console.log(s.padEnd(3)+' '+JSON.stringify(r[s]));
    console.log('');
  }
}
